sys_ux_data_broker_transform.script:
function transform(input) {
    var kpiProperties = [
        'sam.foundation.current.users.kpi',
        'sam.foundation.current.company.kpi',
        'sam.foundation.current.location.kpi',
        'sam.foundation.current.costcenter.kpi',
        'sam.foundation.current.businessunit.kpi',
        'sam.foundation.current.department.kpi'
    ];

    var kpiValues = {
        'users_kpi': [],
        'company_kpi': [],
        'location_kpi': [],
        'costcenter_kpi': [],
        'businessunit_kpi': [],
        'department_kpi': [],
        'custombulk_kpi': []
    };

    function fetchKPIs(propertyName) {
        var kpis = [];
        var propertyValue = gs.getProperty(propertyName);

        if (propertyValue) {
            try {
                gs.log("Raw property value: " + propertyValue);
                kpis = JSON.parse(propertyValue);
            } catch (e) {
                gs.log("Error parsing " + propertyName + ": " + e.message);
            }
        }
        return kpis;
    }

    function fetchCustomBulk() {
        var propertyValue = gs.getProperty('custombulk.property');
        if (!propertyValue) {
            gs.log("No custom bulk properties found.");
            return [];
        }

        try {
            var customBulkData = JSON.parse(propertyValue);
            var formattedData = [];

            Object.keys(customBulkData).forEach(function (key) {
                formattedData.push({
                    'name': key,
                    'short_description': customBulkData[key].short_description || '',
                    'description': customBulkData[key].description || '',
                    'instruction': customBulkData[key].instruction || ''
                });
            });

            return formattedData;
        } catch (e) {
            gs.log("Error parsing custombulk.property: " + e.message);
            return [];
        }
    }

    function getTotalCount(tableName) {
        try {
            var gr = new GlideAggregate(tableName);
            gr.addAggregate('COUNT');
            gr.query();
            return gr.next() ? gr.getAggregate('COUNT') : 0;
        } catch (error) {
            gs.log("Error counting records in table " + tableName + ": " + error.message);
            return 0;
        }
    }

    function processKPI(kpis, kpiType) {
        var totalQueryCount = 0;
        var totalCount = 0;
        var kpiCount = 0;

        if (Array.isArray(kpis)) {
            kpis.forEach(function(kpi) {
                if (kpi.table && kpi.field) {
                    var query = kpi.type === "duplicate" && kpi.groupBy
                        ? getDuplicateCount(kpi.table, kpi.groupBy, kpi.field)
                        : getqueryCount(kpi.table, kpi.field);

                    var tableCount = getTotalCount(kpi.table);
                    totalCount += tableCount;
                    totalQueryCount += query;
                    kpiCount++;

                    var percentage = tableCount > 0 ? ((query / tableCount) * 100).toFixed(2) : 0;

                    kpiValues[kpiType].push({
                        'kpi': kpi.kpi,
                        'usecase': kpi.description,
                        'table': kpi.table,
                        'query': query,
                        'average': percentage,
                        'totalCount': tableCount,
                        'action': kpi.recommendation
                    });
                }
            });
        }

        kpiValues[kpiType + '_average'] = totalCount > 0 ? ((totalQueryCount / totalCount) * 100).toFixed(2) : 0;
    }

    function getqueryCount(tableName, query) {
        try {
            var gr = new GlideAggregate(tableName);
            if (query !== "none") {
                gr.addEncodedQuery(query);
            }
            gr.addAggregate('COUNT');
            gr.query();
            return gr.next() ? gr.getAggregate('COUNT') : 0;
        } catch (error) {
            gs.log("Error querying table " + tableName + ": " + error.message);
            return 0;
        }
    }

    function getDuplicateCount(tableName, groupBy, query) {
        try {
            var gr = new GlideAggregate(tableName);
            gr.addEncodedQuery(query);
            gr.addAggregate('COUNT');
            gr.query();

            var duplicateCount = 0;
            while (gr.next()) {
                var count = parseInt(gr.getAggregate('COUNT'), 10);
                if (count > 1) {
                    duplicateCount++;
                }
            }
            return duplicateCount;
        } catch (error) {
            gs.log("Error querying table " + tableName + ": " + error.message);
            return 0;
        }
    }

    kpiProperties.forEach(function(property, index) {
        var kpiType = Object.keys(kpiValues)[index];
        var kpis = fetchKPIs(property);
        processKPI(kpis, kpiType);
    });

    kpiValues['custombulk_kpi'] = fetchCustomBulk();

    return kpiValues;
}
